/* From Uiverse.io by Yaya12085 - Tags: card */
.__UIV_SCOPE__ .card {
  max-width: 350px;
  background-color: rgb(7 16 45);
  background: linear-gradient(to top right, rgb(7 16 45), rgb(58 60 84));
  background: -webkit-linear-gradient(to top right, rgb(7 16 45), rgb(58 60 84));
  display: flex;
  flex-direction: column;
  padding: 20px;
  border-radius: 20px;
  border: 1px solid rgb(84 90 106);
}

.__UIV_SCOPE__ .small-text, .__UIV_SCOPE__ .title, .__UIV_SCOPE__ .desc {
  font-weight: 600;
}

.__UIV_SCOPE__ .title,.__UIV_SCOPE__ .desc {
  margin: 8px 0;
}

.__UIV_SCOPE__ .small-text {
  color: #488aec;
  font-size: 14px;
}

.__UIV_SCOPE__ .title {
  color: #fff;
  font-size: 26px;
  line-height: 26px;
}

.__UIV_SCOPE__ .desc {
  color: rgb(151 153 167);
  font-size: 13px;
}

.__UIV_SCOPE__ .buttons {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-top: 10px;
}

.__UIV_SCOPE__ .button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-radius: 10px;
  padding: 6px;
  text-decoration: none;
}

.__UIV_SCOPE__ .button:first-child {
  box-shadow: 0 4px 6px -1px #488aec31, 0 2px 4px -1px #488aec17;
  background-color: #488aec;
}

.__UIV_SCOPE__ .button:last-child {
  box-shadow: 0 4px 6px -1px #0b162531, 0 2px 4px -1px #0e192b17;
  background-color: #fff;
}

.__UIV_SCOPE__ .icon {
  height: 25px;
  width: 25px;
}

.__UIV_SCOPE__ .icon svg {
  width: 100%;
  height: 100%;
}

.__UIV_SCOPE__ .icon svg:last-child {
  fill: #000
}

.__UIV_SCOPE__ .button-text {
  display: flex;
  flex-direction: column;
  margin-left: 8px;
}

.__UIV_SCOPE__ .button-text span:first-child {
  font-size: 12px;
  font-weight: 600;
}

.__UIV_SCOPE__ .google span:first-child {
  color: rgb(219 206 253);
}

.__UIV_SCOPE__ .apple span:first-child {
  color: rgb(81 87 108);
}

.__UIV_SCOPE__ .google span:last-child {
  color: #fff;
  font-weight: 800;
}

.__UIV_SCOPE__ .apple span:last-child {
  color: #000;
  font-weight: 800;
}
